using Godot;
using Verdant.Forge;
namespace Verdant.Battle;
public partial class Arena : Control
{
    public static MonsterSpec? WorkshopMonster {get;set;}
    readonly List<ActorRecipe>[] teams={new(),new(),new(),new()};
    readonly List<ActorRecipe> cast=new();readonly List<SpriteCache> cache=new();
    readonly Dictionary<string,Button> buttons=new();
    OptionButton left=null!,right=null!;HFlowContainer specialControls=null!;readonly List<ImageTexture> icons=new();readonly List<(Button button,int id,string name)> skillButtons=new();bool commanded;int selected;SpinBox seed=null!,quantity=null!;Label status=null!,roster=null!;
    BattleSimulation? sim;BattleSpec? previous;Fighter[] sorted=Array.Empty<Fighter>();ImageTexture? terrain;
    bool paused=true,bars=true,ranges;int speed=1;double accumulator;int shownTick=-1;
    readonly Vector2 origin=new(80,240);
    static readonly Color Ink=new("151829"),Energy=new("c1dceb"),Highlight=new("f0f0e5"),HitText=new("fff0c7"),HealText=new("a5d889");
    static readonly Color[] TeamColors={new("6aa9df"),new("e58a78"),new("83c894"),new("b69ad4")};
    public override void _Ready()
    {
        TextureFilter=TextureFilterEnum.Nearest;var top=new VBoxContainer{Position=new(40,24),Size=new(1360,210)};AddChild(top);
        top.AddChild(new Label{Text="VERDANT / ARENA DO VALE · combate automático",Theme=null});
        var nav=new HFlowContainer();top.AddChild(nav);Button(nav,"Elenco",()=>GetTree().ChangeSceneToFile("res://pixel_demo/PixelDemo.tscn"));Button(nav,"Oficina",()=>GetTree().ChangeSceneToFile("res://workshop/Workshop.tscn"));
        Button(nav,"Guia de especiais",()=>GetTree().ChangeSceneToFile("res://battle/SpecialGallery.tscn"));
        seed=new SpinBox{MinValue=1,MaxValue=999999,Step=1,Value=42,CustomMinimumSize=new(140,0)};nav.AddChild(new Label{Text="Semente"});nav.AddChild(seed);quantity=new SpinBox{MinValue=1,MaxValue=40,Step=1,Value=3};nav.AddChild(new Label{Text="Quantidade"});nav.AddChild(quantity);
        var setup=new HFlowContainer();top.AddChild(setup);left=Selector(setup);Button(setup,"Adicionar azul",()=>Add(0,left.Selected));right=Selector(setup);right.Selected=8;Button(setup,"Adicionar coral",()=>Add(1,right.Selected));Button(setup,"Limpar times",()=>{foreach(var team in teams)team.Clear();Summary();});Button(setup,"Sortear confronto",()=>{seed.Value=GD.Randi()%999999+1;Randomize();});
        Button(setup,"Adicionar jade",()=>Add(2,right.Selected));Button(setup,"Adicionar violeta",()=>Add(3,right.Selected));
        var controls=new HFlowContainer();top.AddChild(controls);Button(controls,"Iniciar",Start);Button(controls,"Pausar",()=>paused=!paused);Button(controls,"Velocidade",()=>{speed=speed==4?1:speed*2;buttons["Velocidade"].Text=$"Velocidade {speed}×";});Button(controls,"Passo",()=>{paused=true;sim?.Step();QueueRedraw();});Button(controls,"Barras",()=>{bars=!bars;QueueRedraw();});Button(controls,"Alcances",()=>{ranges=!ranges;QueueRedraw();});Button(controls,"Repetir",Repeat);Button(controls,"Nova batalha",()=>{seed.Value=seed.Value%999999+1;Randomize();Start();});
        Button(controls,"Comandar azul",()=>{commanded=!commanded;sim?.SetManual(0,commanded);});Button(controls,"Recuar selecionado",()=>{if(sim!=null&&sim.Fighters[selected].Spec.Team==0)sim.Retreat(selected);});
        specialControls=new HFlowContainer{Position=new(80,900),Size=new(1280,44)};AddChild(specialControls);
        roster=new Label();top.AddChild(roster);status=new Label{Position=new(80,860),Size=new(1280,75),AutowrapMode=TextServer.AutowrapMode.WordSmart};AddChild(status);
        BuildTerrain();teams[0].AddRange(new[]{ActorRecipe.FromHero(0),ActorRecipe.FromHero(3),ActorRecipe.FromHero(6)});for(ulong i=1;i<=3;i++)teams[1].Add(ActorRecipe.FromMonster(i));if(WorkshopMonster is {} edited)teams[1][0]=new(edited.Id,null,edited);Summary();status.Text="Monte os times e pressione Iniciar. A semente reproduz o confronto.";
        var args=OS.GetCmdlineUserArgs();if(args.Contains("--battle-ui-test"))Test();if(args.Contains("--battle-capture"))Capture();if(args.Contains("--battle-benchmark"))Benchmark();if(args.Contains("--battle-benchmark-small"))Benchmark(6);
    }
    OptionButton Selector(Container p){var s=new OptionButton();foreach(var h in ForgeRoster.All)s.AddItem(h.Name);s.AddItem("Herói por semente");foreach(var f in Enum.GetNames<MonsterFamily>())s.AddItem(f);p.AddChild(s);return s;}
    void Button(Container p,string name,Action a){var b=new Button{Text=name};b.Pressed+=()=>{try{a();}catch(Exception e){status.Text=e.Message;}};p.AddChild(b);buttons[name]=b;}
    void Add(int team,int choice){for(int i=0;i<(int)quantity.Value&&teams[team].Count<40;i++){ulong s=(ulong)seed.Value+(ulong)(teams[team].Count*31+team*100);teams[team].Add(choice<7?ActorRecipe.FromHero(choice):choice==7?ActorRecipe.Generated(s):ActorRecipe.FromMonster(s,(MonsterFamily)(choice-8)));}Summary();}
    void Summary(){roster.Text=string.Join(" · ",teams.Select((t,i)=>$"Time {i+1}: {t.Count}/40"))+" · clique em uma unidade para selecionar; 1–6: especiais";}
    void Randomize(){foreach(var team in teams)team.Clear();var r=new Rng((ulong)seed.Value);for(int side=0;side<2;side++)for(int i=0;i<(int)quantity.Value;i++){int pick=r.Int(0,17);ulong s=r.Next();teams[side].Add(pick<7?ActorRecipe.FromHero(pick):pick==7?ActorRecipe.Generated(s):ActorRecipe.FromMonster(s,(MonsterFamily)(pick-8)));}Summary();}
    void Start(){if(teams.Count(t=>t.Count>0)<2)throw new InvalidOperationException("Monte pelo menos dois times.");foreach(var c in cache.Distinct())c.Dispose();cache.Clear();cast.Clear();var fighters=new List<FighterSpec>();for(int team=0;team<teams.Length;team++)foreach(var r in teams[team]){cast.Add(r);fighters.Add(r.Fighter(team));}var shared=new Dictionary<ActorRecipe,SpriteCache>();foreach(var r in cast){if(!shared.TryGetValue(r,out var frames)){frames=new(r);shared.Add(r,frames);}cache.Add(frames);}previous=new((ulong)seed.Value,fighters.ToArray(),Obstacles:new[]{new Obstacle(130,74,12,18),new Obstacle(185,112,18,12)});sim=null;Repeat();BuildSpecialButtons();}
    void BuildSpecialButtons(){skillButtons.Clear();foreach(var n in specialControls.GetChildren()){specialControls.RemoveChild(n);n.QueueFree();}foreach(var i in icons)i.Dispose();icons.Clear();if(sim==null)return;int index=0;foreach(var f in sim.Fighters.Where(f=>f.Spec.Team==0).Take(6)){var ability=sim.Ability(f);using var img=ForgeEffects.Icon(ability.Id).Image();img.Resize(32,32,Image.Interpolation.Nearest);var icon=ImageTexture.CreateFromImage(img);icons.Add(icon);int id=f.Id;var b=new Button{Text=$"{++index} {ability.Name}",Icon=icon,TooltipText=$"Recarga {ability.Cooldown/30.0:F1}s · {ability.Shape} · "+string.Join(", ",ability.Effects.Select(Abilities.Describe))};b.Pressed+=()=>{selected=id;sim?.CommandSpecial(id);};specialControls.AddChild(b);skillButtons.Add((b,id,$"{index} {ability.Name.Split(' ')[0]}"));}}
    void SyncSummons(){if(sim==null)return;while(cache.Count<sim.Fighters.Length){var f=sim.Fighters[cache.Count];cast.Add(cast[f.ParentId]);cache.Add(cache[f.ParentId]);}if(sorted.Length!=sim.Fighters.Length)sorted=sim.Fighters.ToArray();}
    public override void _UnhandledInput(InputEvent e){if(sim==null)return;if(e is InputEventKey key&&key.Pressed&&!key.Echo&&key.Keycode>=Key.Key1&&key.Keycode<=Key.Key6){int slot=(int)(key.Keycode-Key.Key1);var fighters=sim.Fighters.Where(f=>f.Spec.Team==0&&f.ParentId<0).Take(6).ToArray();if(slot<fighters.Length){selected=fighters[slot].Id;sim.CommandSpecial(selected);}}if(e is InputEventMouseButton mouse&&mouse.Pressed){var p=(mouse.Position-origin)/4;if(mouse.ButtonIndex==MouseButton.Left){selected=sim.Fighters.OrderBy(f=>new Vector2(f.Position.X,f.Position.Y).DistanceSquaredTo(p)).First().Id;}if(mouse.ButtonIndex==MouseButton.Right&&commanded&&sim.Fighters[selected].Spec.Team==0){if(paused&&sim.Tick==0)sim.Place(selected,new(p.X,p.Y));else sim.MoveOrder(selected,new(p.X,p.Y));}}}
    void Repeat(){if(previous==null)return;var replay=sim?.Inputs.ToArray();if(cache.Count>previous.Fighters.Count){cache.RemoveRange(previous.Fighters.Count,cache.Count-previous.Fighters.Count);cast.RemoveRange(previous.Fighters.Count,cast.Count-previous.Fighters.Count);}sim=new(previous);if(replay!=null)sim.QueueReplay(replay);if(replay==null)sim.SetManual(0,commanded);sorted=sim.Fighters.ToArray();accumulator=0;paused=false;shownTick=-1;QueueRedraw();}
    public override void _Process(double dt)
    {
        if(sim==null)return;if(!paused&&!sim.Finished){accumulator+=Math.Min(dt,.25)*speed;while(accumulator>=1.0/30){sim.Step();accumulator-=1.0/30;}}
        SyncSummons();if(shownTick!=sim.Tick&&sim.Tick%3==0){foreach(var (button,id,name) in skillButtons){var f=sim.Fighters[id];button.Disabled=!f.Alive||f.Retreated||f.SpecialCooldown>0||f.CastRemaining>0||f.Statuses.ContainsKey(EffectKind.Stun);button.Text=name+(f.SpecialCooldown>0?$" {f.SpecialCooldown/30.0:F1}s":" pronto");}}if(shownTick!=sim.Tick){shownTick=sim.Tick;status.Text=sim.Finished?$"{(sim.Winner<0?"Empate por tempo":"Vitória do time "+(sim.Winner+1))} · {sim.Tick/30.0:F1}s · "+string.Join(" | ",sim.Fighters.GroupBy(f=>f.Spec.Team).Select(g=>$"Time {g.Key+1}: {g.Sum(f=>f.Damage)} dano / {g.Sum(f=>f.Kills)} abates")):$"Semente {sim.Spec.Seed} · {sim.Tick/30.0:F1}s · {(paused?"pausado":speed+"×")} · Azul {sim.Fighters.Count(f=>f.Alive&&f.Spec.Team==0)} × Coral {sim.Fighters.Count(f=>f.Alive&&f.Spec.Team==1)}";if(!sim.Finished&&selected<sim.Fighters.Length){var focus=sim.Fighters[selected];status.Text+=$" · Seleção: {focus.Spec.Group}, escudo {focus.Shield}";if(focus.Statuses.Count>0)status.Text+=" · "+string.Join(", ",focus.Statuses.Select(s=>$"{Abilities.EffectNames[s.Key]} {(s.Value.Until-sim.Tick)/30.0:F1}s"));}QueueRedraw();}
    }
    void BuildTerrain(){var px=new Raster(320,150);px.Rect(0,0,320,150,new Color("82985a"));px.Rect(8,8,304,136,new Color("92784c"));var r=new Rng(902);for(int i=0;i<700;i++){int x=r.Int(0,320),y=r.Int(0,150);px.Rect(x,y,2,1,new Color(i%3==0?"a58a5a":"7b693f"));}for(int i=0;i<18;i++){int x=r.Int(0,320),y=i%2==0?3:145;px.Rect(x,y,4,2,new Color("555b58"));px.Rect(x,y,3,1,new Color("9da38b"));}using var img=px.Image();terrain=ImageTexture.CreateFromImage(img);}
    Vector2 Screen(System.Numerics.Vector2 p)=>origin+new Vector2(MathF.Round(p.X)*4,MathF.Round(p.Y)*4);
    public override void _Draw()
    {
        if(terrain!=null)DrawTextureRect(terrain,new(origin,new(1280,600)),false);if(sim==null)return;
        SyncSummons();foreach(var o in sim.Spec.Obstacles??Array.Empty<Obstacle>()){DrawRect(new(origin+new Vector2(o.X*4,o.Y*4),new(o.Width*4,o.Height*4)),Ink);DrawRect(new(origin+new Vector2(o.X*4+4,o.Y*4+4),new(o.Width*4-8,o.Height*4-8)),new Color("829fb9"));}
        Array.Sort(sorted,(a,b)=>a.Position.Y.CompareTo(b.Position.Y));
        foreach(var f in sorted){if(f.Retreated)continue;int elapsed=sim.Tick-f.DeathTick;if(!f.Alive&&elapsed>=23)continue;var p=Screen(f.Position);var c=cache[f.Id];MonsterMotion m;double t;
            if(!f.Alive){m=MonsterMotion.Death;t=elapsed/30.0;}else if(f.CastRemaining>0){m=MonsterMotion.Cast;t=(sim.Tick-f.LastSpecial)/30.0;}else if(sim.Tick-f.LastSpecial<30){m=MonsterMotion.Special;t=(sim.Tick-f.LastSpecial)/30.0;}else if(sim.Tick-f.LastHit<12){m=MonsterMotion.Hurt;t=(sim.Tick-f.LastHit)/30.0;}else if(sim.Tick-f.LastAttack<22){m=MonsterMotion.Attack;t=(sim.Tick-f.LastAttack)/30.0;}else{m=f.Moving?MonsterMotion.Walk:MonsterMotion.Idle;t=sim.Tick/30.0;}
            if(ranges&&f.Alive)DrawArc(p,f.Spec.Stats.Range*4,0,Mathf.Tau,32,new Color("d8ce97"),1,false);
            var start=p-new Vector2(c.Size/2*4,(c.Size-3)*4);bool flip=f.Target>=0&&sim.Fighters[f.Target].Position.X<f.Position.X;
            DrawTextureRect(c.Get(m,t),flip?new(start+new Vector2(c.Size*4,0),new(-c.Size*4,c.Size*4)):new(start,new(c.Size*4,c.Size*4)),false);

        }
        foreach(var f in sorted)if(f.Alive&&!f.Retreated){var p=Screen(f.Position);if(bars){var at=p-new Vector2(24,cache[f.Id].Size*4+2);DrawRect(new(at,new(48,8)),Ink);DrawRect(new(at+new Vector2(2,2),new(44f*f.Health/f.Spec.Stats.Health,4)),TeamColors[f.Spec.Team%4]);if(f.Shield>0)DrawRect(new(at-new Vector2(0,4),new(Math.Min(48,f.Shield),2)),Energy);}DrawRect(new(p+new Vector2(-20,10),new(40,4)),Ink);DrawRect(new(p+new Vector2(-20,10),new(40*Math.Clamp(1-f.SpecialCooldown/210f,0,1),4)),Energy);if(f.Id==selected)DrawRect(new(p+new Vector2(-24,16),new(48,4)),Highlight);}
        foreach(var shot in sim.Projectiles){var p=Screen(shot.Position)-new Vector2(0,28);DrawRect(new(p,new(8,4)),Highlight);}
        for(int i=sim.Events.Count-1;i>=0;i--){var e=sim.Events[i];int age=sim.Tick-e.Tick;if(age>25)break;var p=origin+new Vector2(MathF.Round(e.X)*4,MathF.Round(e.Y)*4);
            if(e.Kind=="damage"||e.Kind=="heal"){if(age<4){DrawRect(new(p+new Vector2(-8,-40),new(16,4)),HitText);DrawRect(new(p+new Vector2(-2,-46),new(4,16)),HitText);}}
            if(e.Kind.StartsWith("effect:")&&age<12){var ability=sim.Ability(sim.Fighters[e.Source]);var source=Screen(sim.Fighters[e.Source].Position);var dir=(p-source).Normalized();if(dir.LengthSquared()<.01f)dir=Vector2.Right;float radius=ability.Radius*Math.Min(1,(age+3)/8f);for(int k=0;k<24;k++){Vector2 point;float fraction=k/23f;if(ability.Shape==TargetShape.Line)point=source+dir*radius*fraction*4;else if(ability.Shape==TargetShape.Cone){float angle=dir.Angle()+(-.6f+1.2f*fraction);point=source+Vector2.FromAngle(angle)*radius*4;}else {float angle=k*Mathf.Tau/24;point=p+new Vector2(MathF.Cos(angle)*radius*4,MathF.Sin(angle)*radius*2);}point=new(MathF.Round(point.X/4)*4,MathF.Round(point.Y/4)*4);DrawRect(new(point,new(4,4)),Energy);}}

        }
        for(int i=sim.Events.Count-1;i>=0;i--){var e=sim.Events[i];int age=sim.Tick-e.Tick;if(age>25)break;if(e.Kind is "damage" or "heal"){var p=origin+new Vector2(MathF.Round(e.X)*4,MathF.Round(e.Y)*4);DrawString(ThemeDB.FallbackFont,p+new Vector2(-8,-50-age),e.Kind=="heal"?"+"+e.Amount:e.Amount.ToString(),HorizontalAlignment.Left,-1,16,e.Kind=="heal"?HealText:HitText);}}

    }
    async void Test(){await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);int checks=0;void Check(bool x,string m){checks++;if(!x)throw new Exception(m);}try{buttons["Limpar times"].EmitSignal(Godot.Button.SignalName.Pressed);quantity.Value=2;left.Selected=3;right.Selected=11;buttons["Adicionar azul"].EmitSignal(Godot.Button.SignalName.Pressed);buttons["Adicionar coral"].EmitSignal(Godot.Button.SignalName.Pressed);Check(teams[0].Count==2&&teams[1].Count==2,"teams");buttons["Adicionar jade"].EmitSignal(Godot.Button.SignalName.Pressed);Check(teams[2].Count==2,"third team");buttons["Iniciar"].EmitSignal(Godot.Button.SignalName.Pressed);Check(sim!=null&&!paused,"start");using(var cached=cache[0].Get(MonsterMotion.Special,.375).GetImage())using(var expected=new CompactAdventurer(cast[0].Hero!).Render(.375,AdventurerMotion.Special).Image())Check(cached.GetData().SequenceEqual(expected.GetData()),"atlas matches hero render");Check(sim!.Fighters.Select(f=>f.Spec.Team).Distinct().Count()==3,"three simulation teams");buttons["Comandar azul"].EmitSignal(Godot.Button.SignalName.Pressed);sim.Place(0,new(100,90));sim.Place(2,new(140,90));buttons["Pausar"].EmitSignal(Godot.Button.SignalName.Pressed);Check(paused,"pause");int t=sim!.Tick;buttons["Passo"].EmitSignal(Godot.Button.SignalName.Pressed);Check(sim.Tick==t+1,"step");buttons["Velocidade"].EmitSignal(Godot.Button.SignalName.Pressed);Check(speed==2,"speed2");buttons["Velocidade"].EmitSignal(Godot.Button.SignalName.Pressed);Check(speed==4,"speed4");for(int i=0;i<60;i++)sim.Step();specialControls.GetChild<Button>(0).EmitSignal(Godot.Button.SignalName.Pressed);Check(sim.Fighters[0].LastSpecial==sim.Tick,"manual special button");Check(!sim.CommandSpecial(0),"special cooldown");sim.Run();Check(sim.Finished,"finish");var events=sim.Events.ToArray();buttons["Repetir"].EmitSignal(Godot.Button.SignalName.Pressed);sim!.Run();Check(events.SequenceEqual(sim.Events),"repeat");GD.Print($"BATTLE_UI_PASS checks={checks}");GetTree().Quit();}catch(Exception e){GD.PrintErr(e);GetTree().Quit(1);}}
    async void Capture(){Start();paused=true;string dir=ProjectSettings.GlobalizePath("user://battle-frames");Directory.CreateDirectory(dir);for(int f=0;f<48;f++){for(int i=0;i<8;i++)sim!.Step();QueueRedraw();await ToSignal(RenderingServer.Singleton,RenderingServer.SignalName.FramePostDraw);using var img=GetViewport().GetTexture().GetImage();img.SavePng(Path.Combine(dir,$"arena-{f:D2}.png"));}GD.Print("BATTLE_CAPTURE "+dir);GetTree().Quit();}
    async void Benchmark(int perTeam=20){quantity.Value=perTeam;Randomize();Start();for(int tick=0;tick<180;tick++)sim!.Step();SyncSummons();await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);var times=new List<double>();for(int f=0;f<360;f++){var watch=System.Diagnostics.Stopwatch.StartNew();await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);times.Add(watch.Elapsed.TotalMilliseconds);}times.Sort();GD.Print($"BATTLE_BENCH fighters={cast.Count} median_ms={times[180]:F2} p95_ms={times[342]:F2}");GetTree().Quit();}
    public override void _ExitTree(){foreach(var c in cache.Distinct())c.Dispose();foreach(var icon in icons)icon.Dispose();terrain?.Dispose();}
}
